property.code:
/* Metadata of an RFC: label/value pairs on two columns when the screen is wide enough. The definition list
   markup is kept as is because in-place editing relies on the dt/dd pairs. */
.rfc-metadata dl {
  display: grid;
  grid-template-columns: max-content minmax(0, 1fr);
  column-gap: 1.5em;
  row-gap: .5em;
  align-items: baseline;
  margin-bottom: 1.5em;
}
.rfc-metadata dl > dt,
.rfc-metadata dl > dd {
  margin: 0;
}
@media (min-width: 768px) {
  .rfc-metadata dl {
    grid-template-columns: max-content minmax(0, 1fr) max-content minmax(0, 1fr);
    column-gap: 2em;
  }
}
/* The abstract and the content keep the vertical layout, with a little more room between them. */
.rfc-body dl > dd {
  margin-bottom: 1.5em;
}
